<script setup lang="ts">
import {localize} from './localization';

import {computed,inject,ref,watch} from 'vue';
import {useSession} from './store';
import {useDraftHistory} from './modules/useDraftHistory';
import CutAssemblyPreview from './CutAssemblyPreview.vue';
import type {UnwrapOptions} from '../../../packages/schema/index';
const advanced=inject('advancedMode',ref(false));
const props=defineProps<{language:'zh'|'en'}>(),emit=defineEmits<{accepted:[id:string]}>(),store=useSession(),zh=computed(()=>props.language==='zh'),surface=computed(()=>store.data.project?.surface),run=computed(()=>store.data.project?.surfaceRun),ack=ref(false),unwrapping=ref(false);
watch(()=>[store.data.project?.id,store.data.project?.revision],()=>{ack.value=false;});
async function cancelUnwrap(){const p=store.data.project;if(p)await window.fpcad.cancelSurface(p.id,p.revision);}
const unwrapOptions=ref<UnwrapOptions>({method:'arap',partitionStrategy:'design',automaticCuts:true,colorBoundaryCuts:true,normalAngleDeg:60,maxFacesPerPatch:400,iterations:30,optimizeCuts:true,searchPasses:3,maxPieces:500});
const historyPanel=ref<HTMLElement>(),history=useDraftHistory(()=>unwrapOptions.value,value=>{unwrapOptions.value=value;},()=>!!historyPanel.value?.getClientRects().length,()=>store.busy);
function colorMode(enabled:boolean){history.begin();unwrapOptions.value.colorBoundaryCuts=enabled;if(!advanced.value)unwrapOptions.value.partitionStrategy='design';history.end();}
function partitionMode(angle:number){history.begin();unwrapOptions.value.normalAngleDeg=angle;if(angle===120||angle===60)unwrapOptions.value.maxFacesPerPatch=angle===120?2000:400;history.end();}
async function unwrap(){const p=store.data.project;if(!p)return;unwrapping.value=true;try{await store.run(()=>window.fpcad.unwrapSurface(p.id,p.revision,JSON.parse(JSON.stringify({...unwrapOptions.value,partitionStrategy:advanced.value?(unwrapOptions.value.partitionStrategy??'design'):'design'}))));ack.value=false;}finally{unwrapping.value=false;}}
async function accept(){const p=store.data.project;if(p&&await store.run(()=>window.fpcad.acceptSurface(p.id,p.revision,ack.value)))emit('accepted',store.data.project?.pieces.at(-1)?.id??'');}

</script>
<template><section ref="historyPanel" class="unwrap-tool-section"><p class="tool-note">{{zh?'1. 完成花纹和裁剪线 → 2. 点击裁切 → 3. 审阅并保存':localize('1. Finish markings and cut lines → 2. Cut → 3. Review and save')}}</p><div class="unwrap-controls"><label v-if="advanced">{{zh?'展开算法':localize('Unwrap solver')}}<select v-model="unwrapOptions.method"><option value="lscm">LSCM</option><option value="arap">LSCM + ARAP</option></select></label><label v-if="advanced"><input v-model="unwrapOptions.automaticCuts" type="checkbox">{{zh?'自动切缝':localize('Automatic cuts')}}</label><label v-if="advanced"><input v-model="unwrapOptions.optimizeCuts" type="checkbox">{{zh?'高失真试切优化':localize('Trial cuts for high distortion')}}</label><label><input :checked="unwrapOptions.colorBoundaryCuts" type="checkbox" @change="colorMode(($event.target as HTMLInputElement).checked)">{{zh?'按花纹颜色拆分裁片':localize('Separate pieces at color boundaries')}}</label><small>{{zh?'默认按颜色边界与自定义裁线形成裁片，仅在展开需要时补缝；请审阅接缝与失真。':localize('Color boundaries and custom cut lines define the pieces. Necessary unwrap seams may be added; review seams and distortion.')}}</small><label v-if="advanced&&unwrapOptions.partitionStrategy==='mesh'&&unwrapOptions.colorBoundaryCuts">{{zh?'自动分片策略':localize('Automatic partition strategy')}}<select :value="unwrapOptions.normalAngleDeg" @change="partitionMode(Number(($event.target as HTMLSelectElement).value))" :aria-label="zh?'自动分片策略':localize('Automatic partition strategy')"><option :value="120">{{zh?'较少额外接缝':localize('Fewer additional seams')}}</option><option :value="60">{{zh?'更细的曲面分片':localize('Finer surface patches')}}</option><option v-if="![60,120].includes(unwrapOptions.normalAngleDeg??60)" :value="unwrapOptions.normalAngleDeg">{{zh?'自定义':localize('Custom')}} · {{unwrapOptions.normalAngleDeg}}°</option></select></label><small v-if="advanced&&unwrapOptions.partitionStrategy==='mesh'&&unwrapOptions.colorBoundaryCuts">{{zh?'颜色边界会继续拆分裁片。较少额外接缝可减少碎片，仍需审阅曲面失真；自定义裁剪线会保留。':localize('Color boundaries split the patches further. Fewer additional seams reduces fragmentation; review surface distortion. Custom cut lines are preserved.')}}</small><label v-if="advanced">{{zh?'分片方式':localize('Partition mode')}}<select v-model="unwrapOptions.partitionStrategy" aria-label="分片方式"><option value="design">{{zh?'按颜色与裁线设计':localize('Color and cut-line design')}}</option><option value="mesh">{{zh?'按网格分片（兼容模式）':localize('Mesh patches (compatibility)')}}</option></select></label><details v-if="advanced" class="solver-settings"><summary>{{zh?'求解参数':localize('Solver settings')}}</summary><label v-if="unwrapOptions.partitionStrategy==='mesh'">{{zh?'法线分片角度 °':localize('Normal angle °')}}<input v-model.number="unwrapOptions.normalAngleDeg" type="number" min="5" max="180"></label><label v-if="unwrapOptions.partitionStrategy==='mesh'">{{zh?'每片最大面数':localize('Faces per patch')}}<input v-model.number="unwrapOptions.maxFacesPerPatch" type="number" min="1" max="2000"></label><label>{{zh?'迭代次数':localize('Iterations')}}<input v-model.number="unwrapOptions.iterations" type="number" min="1" max="100"></label><label>{{zh?'试切搜索轮次':localize('Cut search passes')}}<input v-model.number="unwrapOptions.searchPasses" type="number" min="1" max="5"></label><label>{{zh?'最大裁片数':localize('Maximum pieces')}}<input v-model.number="unwrapOptions.maxPieces" type="number" min="2" max="500"></label></details><button :disabled="store.busy||!surface" @click="unwrap">{{zh?'裁切并计算版型候选':localize('Cut and compute pattern candidate')}}</button><button v-if="unwrapping" @click="cancelUnwrap">{{zh?'取消展开':localize('Cancel unwrap')}}</button></div><p v-if="!surface" class="tool-note">{{zh?'先在“模型管理”页面导入或创建模型。':localize('Import or create a model first.')}}</p> <section v-if="run" class="run-report"><small v-if="advanced&&run.bindings.some(b=>b.report.planarExact)">{{zh?'共面片使用精确毫米投影；轮廓冗余采样清理容差 0.0001 mm。':localize('Planar patches use an exact millimetre projection; redundant boundary tolerance 0.0001 mm.')}}</small><strong>{{run.algorithm}} · {{run.pieces.length}} {{zh?'片':localize('pieces')}} · {{run.accepted?(zh?'已接受':localize('Accepted')):(zh?'候选待审阅':localize('Candidate for review'))}}</strong><p>{{zh?'最大面积误差':localize('Maximum area error')}} {{(run.bindings.reduce((max,b)=>Math.max(max,b.report.areaErrorMax),0)*100).toFixed(2)}}% · {{zh?'最大边长误差':localize('Maximum edge error')}} {{(run.bindings.reduce((max,b)=>Math.max(max,b.report.edgeErrorMax),0)*100).toFixed(2)}}%</p><p v-if="run.designCutReport" class="design-cut-report">{{zh?'设计材料域':localize('Designed material domains')}} {{run.designCutReport.materialDomains}} · {{zh?'自定义裁线':localize('User cut lines')}} {{run.designCutReport.userSeams}} · {{zh?'必要补缝':localize('Necessary additional seams')}}: {{zh?'拓扑开口':localize('Topology')}} {{run.designCutReport.topologySeams}} / {{zh?'失真修正':localize('Distortion')}} {{run.designCutReport.distortionSeams}} / {{zh?'缝份制造':localize('Manufacturing allowance')}} {{run.designCutReport.manufacturingSeams}}。{{zh?'请在拼接预览检查补缝并审阅失真。':localize('Inspect additional seams and distortion in Cut assembly.')}}</p><p v-if="run.colorCutReport&&(run.colorCutReport.budgetSplits+run.colorCutReport.allowanceSplits+run.colorCutReport.topologySplits)>0" class="color-cut-report">{{zh?'为保留材料并生成可制造裁片，已增加分片接缝：':localize('Additional seams preserve material and produce manufacturable pieces:')}} {{zh?'复杂轮廓':localize('Detailed contours')}} {{run.colorCutReport.budgetSplits}} · {{zh?'内孔缝份':localize('Hole allowances')}} {{run.colorCutReport.allowanceSplits}} · {{zh?'相切边界':localize('Touching boundaries')}} {{run.colorCutReport.topologySplits}}。{{zh?'请在组合预览中检查这些接缝。':localize('Inspect these seams in the assembly preview.')}}</p><details v-if="advanced" class="tool-details"><summary>{{zh?'逐片失真与求解报告':localize('Piece distortion & solver report')}}</summary><div v-for="(binding,i) in run.bindings" :key="binding.pieceId">{{i+1}} · {{binding.report.status}} · {{zh?'面积最大误差':localize('Max area error')}} {{(binding.report.areaErrorMax*100).toFixed(2)}}% · {{zh?'边长最大误差':localize('Max edge error')}} {{(binding.report.edgeErrorMax*100).toFixed(2)}}% · D mean {{binding.report.distortionMean.toFixed(4)}} / p95 {{binding.report.distortionP95.toFixed(4)}} / max {{binding.report.distortionMax.toFixed(4)}}</div>
  <p v-if="run.optimization">{{zh?'试切优化成本':localize('Trial-cut cost')}} {{run.optimization.initialCost.toFixed(5)}} → {{(run.optimization.optimizedCost??run.optimization.finalCost).toFixed(5)}} · {{zh?'补切后成本':localize('Cost after allowance repair')}} {{run.optimization.finalCost.toFixed(5)}} · {{run.optimization.passes}} / {{run.optimization.trials}} · {{zh?'缝份补切轮次':localize('Allowance repair passes')}} {{run.optimization.repairPasses??0}}</p><p v-if="run.cutEdges?.length">{{zh?'自动切缝边数':localize('Automatic cut edges')}}: {{run.cutEdges.length}}</p><div v-for="b in run.bindings.filter(b=>b.report.arap)" :key="b.pieceId+'arap'">ARAP {{b.report.arap?.iterations}} · E {{b.report.arap?.energyBefore.toExponential(3)}} → {{b.report.arap?.energyAfter.toExponential(3)}} · {{b.report.arap?.converged?'Converged':localize('Iteration budget / line search limit')}}</div></details><template v-if="!run.accepted"><label class="distortion-review" v-if="run.bindings.some(b=>b.report.status==='needsReview')"><input v-model="ack" type="checkbox">{{zh?'我已审阅超出实验阈值的失真，仍需材料试做验证':localize('I reviewed distortion above experimental thresholds; material trials remain necessary')}}</label><button :disabled="store.busy||run.bindings.some(b=>b.report.status==='needsReview')&&!ack" @click="accept">{{zh?'确认版型并保存到裁切库（可撤销）':localize('Accept patterns and save to library (undoable)')}}</button></template>
 <details v-if="surface"><summary>{{zh?'裁片组合预览':localize('Cut assembly preview')}}</summary><CutAssemblyPreview :surface="surface" :run="run" :markings="store.data.project?.previewMarkings??store.data.project?.markings" :language="language"/></details></section>
</section></template>
<style scoped>.unwrap-tool-section{padding:15px;border-top:1px solid var(--border)}.unwrap-controls{display:grid;gap:10px}.run-report{margin-top:15px}.run-report strong{display:block}.run-report button{width:100%;margin-top:10px}.tool-note{font-size:11px;line-height:1.7}small{display:block}label{display:block}</style>

